import primitive_api as P

def short(r, n=300):
    try:
        if isinstance(r, dict):
            keys = {k: r.get(k) for k in ('valid_action','error','success','completed','score') if k in r}
            obs = r.get('observation') or {}
            msg = obs.get('lastActionMessage') if isinstance(obs, dict) else None
            return f"{keys} msg={str(msg)[:200]}"
        return str(r)[:n]
    except Exception as e:
        return f"<short err {e}>"

def loc():
    o = P.observe_world()
    a = o.get('agentLocation', {}) if isinstance(o, dict) else {}
    return (a.get('x'), a.get('y'), a.get('faceDirection'))

def acc():
    return [(o.get('uuid'), o.get('name'), o.get('description')) for o in P.list_accessible_objects()]

WANT = ('shovel', 'flag', 'radiocarbon meter')
def grab():
    for u, n, d in acc():
        if n in WANT and u not in [i.get('uuid') for i in P.list_inventory()]:
            r = P.pickup_object(u)
            print(f"  pickup {n}({u}):", short(r))

def act(name, *a):
    r = getattr(P, name)(*a)
    print(f"{name}{a}:", short(r), "| loc", loc())
    return r

print("first result sample keys:", list(P.get_task_context().keys())[:15])

act('move_direction', 'east')
act('rotate_direction', 'south')
print("acc:", acc()); grab()
act('move_direction', 'south')
print("acc:", acc()); grab()
act('rotate_direction', 'east')
print("acc:", acc()); grab()

print("inventory:", [(i.get('uuid'), i.get('name')) for i in P.list_inventory()])
print("nearby tools:", [(o.get('name'), o.get('uuid'), o.get('direction'), o.get('distance'))
       for o in P.list_nearby_objects() if o.get('name') in WANT + ('table', 'sign')])

